command:
$ErrorActionPreference='Stop'; $script=Join-Path $env:TEMP 'known_folder_uia_diag.py'; @'

import ctypes as c, os, subprocess, time
from pathlib import Path
from pywinauto import Desktop

ROOT=Path(r"C:\dev\flyExplorer")
EXE=ROOT/"out"/"winui"/"Release"/"flyExplorer.exe"
profile=Path(os.environ["USERPROFILE"])
proc=subprocess.Popen([str(EXE),str(profile)],cwd=EXE.parent,env=os.environ.copy())
win=None
try:
    end=time.monotonic()+20
    while time.monotonic()<end:
        ws=[w for w in Desktop(backend="uia").windows(process=proc.pid) if "flyExplorer" in w.window_text()]
        if len(ws)==1:
            win=ws[0]; break
        if proc.poll() is not None: break
        time.sleep(.25)
    if not win: raise RuntimeError("window missing")
    time.sleep(4)
    print("WINDOW_TITLE",repr(win.window_text()),flush=True)
    allc=win.descendants()
    left=[x for x in allc if x.element_info.automation_id=="LeftFiles"]
    print("LEFTFILES_COUNT",len(left),flush=True)
    if left:
        items=[x for x in left[0].descendants() if x.element_info.control_type=="ListItem"]
        print("LEFTFILES_LISTITEM_COUNT",len(items),flush=True)
        for i,x in enumerate(items[:120]):
            try:
                print("LEFT_ITEM",i,"NAME",repr(x.element_info.name),"TEXT",repr(x.window_text()),
                      "AID",repr(x.element_info.automation_id),flush=True)
                imgs=[y.element_info.name for y in x.descendants()
                      if y.element_info.control_type=="Image"]
                if imgs: print("LEFT_ITEM_IMAGES",i,repr(imgs),flush=True)
            except Exception as e:
                print("LEFT_ITEM_ERROR",i,repr(e),flush=True)
    print("ALL_LISTITEMS",flush=True)
    for i,x in enumerate([x for x in allc if x.element_info.control_type=="ListItem"][:160]):
        try: print("ANY_ITEM",i,repr(x.element_info.name),repr(x.element_info.automation_id),flush=True)
        except Exception: pass
finally:
    if proc.poll() is None:
        if win:
            c.windll.user32.PostMessageW(win.handle,0x10,0,0)
            try: proc.wait(timeout=8)
            except subprocess.TimeoutExpired:
                proc.terminate();proc.wait(timeout=5)
        else:
            proc.terminate();proc.wait(timeout=5)
print("EXIT",proc.returncode,flush=True)

'@ | Set-Content -LiteralPath $script -Encoding utf8; python -X utf8 $script; $rc=$LASTEXITCODE; Remove-Item $script -Force -ErrorAction SilentlyContinue; exit $rc
